/*
 * zimwiki - bitmap fonts (tables generated by tools/bdf2c.py)
 */
#ifndef FONT_H
#define FONT_H

#include "zw.h"

#define GLYPH_REC 12

typedef struct font {
	const uint8_t *glyphs;	/* GLYPH_REC bytes each, sorted by code point */
	const uint8_t *bits;
	uint16_t count;
	uint8_t ascent, descent;
	uint8_t pad;
} font_t;

/* private use code points drawn as full line height bracket pieces */
#define FONT_PIECE 0xf8e0u

typedef struct glyph {
	const uint8_t *bits;
	uint8_t adv, w, h;
	int8_t xoff, top;
} glyph_t;

extern font_t fonts[];
#include "fonts_gen.h"

/* optional large fallback font loaded from the card (CJK etc.) */
int font_set_fallback(const uint8_t *data, uint32_t len);
/* or: call fn (which calls font_set_fallback) when first needed */
void font_set_fallback_loader(int (*fn)(void));

/* glyph for cp in font f, trying the fallback chain; never fails
 * (unknown characters get a hollow box) */
void font_glyph(int f, uint32_t cp, glyph_t *g);

int font_height(int f);		/* line height in pixels */
int font_ascent(int f);
int font_width(int f, const char *s, size_t len);
const uint8_t *font_ascii_adv(int f);

/* draw UTF-8 text on a 1 bpp buffer; returns the x after the text */
int font_draw(uint8_t *buf, int stride, int rows, int x, int baseline,
	      int f, const char *s, size_t len, int colour);

#endif
